import { Block, type BlockProps } from "@prototyp/skeletor";
import type { FC, PropsWithChildren } from "react";
import { MAX_IPAD_SCREEN_WIDTH } from "shared/const";
import { isIpad } from "shared/utils";

export const IpadScreenWrapper: FC<PropsWithChildren<BlockProps>> = ({
  children,
  ...props
}) => {
  const hasExtraProps = Object.keys(props).length > 0;

  if (!isIpad() && !hasExtraProps) return children;

  if (!isIpad() && hasExtraProps) {
    return <Block {...props}>{children}</Block>;
  }

  return (
    <Block
      flex={1}
      width="100%"
      maxWidth={MAX_IPAD_SCREEN_WIDTH}
      margins={{ marginHorizontal: "auto" }}
      {...props}
    >
      {children}
    </Block>
  );
};

