              value={form.state.name}
              autoCapitalize="none"
              onBlur={() => form.validate("name")}
              onChangeText={(value) => form.update("name", value)}
            />
            <Text
              color="red"
              opacity={form.validation.name === false ? 1 : 0}
              size={TextSize.tiny}
              paddings={[0, 16]}
              absolute
              offsets={{ bottom: -20 }}
            >
              Please enter a valid room name.
            </Text>
          </Block>
          <Block gap={8}>
            <Block
              flexDirection="row"
              align="center"
              justify="space-between"
